private int parseEndOfLine(String headerPart, int end) {
    int i = end;
    while (i >= 0) {
        char c = headerPart.charAt(i);
        if (c == '\n') {
            i = headerPart.lastIndexOf('\r', i - 1);
            break;
        }
        if (c == '\r') {
            if (i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
                break;
            }
        }
        i--;
    }
    return i;
}

private int parseEndOfLine(String headerPart, int end) {
    int idx = headerPart.length() - 1;
    while (idx >= 0) {
        char c = headerPart.charAt(idx);
        if (c == '\n' && idx > 0 && headerPart.charAt(idx - 1) == '\r') {
            return idx - 1;
        }
        if (c == '\n' || c == '\r') {
            return idx;
        }
        idx--;
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    for (int i = end; i > 0; i--) {
        char c = headerPart.charAt(i - 1);
        if (c == '\n') {
            if (i > 1 && headerPart.charAt(i - 2) == '\r') {
                return i - 1;
            }
        }
    }
    return end;
}

