void insertBefore(Bucket bucket){
    // If bucket is null, throw an IllegalArgumentException
    if (bucket == null) {
        throw new IllegalArgumentException("The bucket parameter cannot be null");
    }

    // If the bucket is the same as the head, insert at the head
    if (bucket == head) {
        this.next = head;
        this.prev = head.prev;
        if (head.prev != null) {
            head.prev.next = this;
        }
        head.prev = this;
        return;
    }

    // Find the bucket's previous in the list
    Bucket current = head;
    while (current != null && current.next != bucket) {
        current = current.next;
    }

    // If bucket was not found in the list, throw a RuntimeException
    if (current == null || current.next != bucket) {
        throw new RuntimeException("The specified bucket is not in the list");
    }

    // Insert this bucket before bucket
    this.next = bucket;
    this.prev = current;
    current.next = this;
    bucket.prev = this;
}

void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }
    if (this.previous == null) {
        bucket.next = this;
        bucket.previous = null;
        this.previous = bucket;
    } else {
        bucket.previous = this.previous;
        bucket.next = this;
        this.previous.next = bucket;
        this.previous = bucket;
    }
}

