public void put(LoggingEvent o) {
    if (bufferFull) {
        // Silently drop the event if the buffer is full
        return;
    }
    // Add the event to the buffer
    LoggingEvent[] copy = new LoggingEvent[buffer.length];
    System.arraycopy(buffer, 0, copy, 1, buffer.length - 1);
    copy[0] = o;
    buffer = copy;
    if (buffer.length == 1) {
        bufferFull = true;
    }
}

public void put(LoggingEvent o) {
    int writePosition = this.end + 1;
    if (writePosition == this.buffer.length) {
        writePosition = 0;
    }
    if (this.start != this.bufSize) {
        if (this.head >= this.end) {
            if (this.head == this.bufSize) {
                this.head = 0;
            }
        }
    }
    LoggingEvent[] remoteBuffer = this.getBuffer();
    if (remoteBuffer == null) {
        throw new IllegalStateException("Buffer not enabled");
    }
    remoteBuffer[this.end] = o;
    this.end = writePosition;
    this.bufSize++;
}

