static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (timeBucket < 10000) {
            return timeBucket;
        }
        long year = timeBucket / 10000;
        long month = (timeBucket % 10000) / 100;
        long day = timeBucket % 100;

        // Validate month
        if (month < 1 || month > 12) {
            return timeBucket;
        }

        // Determine max days in this month considering leap years
        int maxDay;
        switch ((int) month) {
            case 2:
                boolean isLeap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
                maxDay = isLeap ? 29 : 28;
                break;
            case 4: case 6: case 9: case 11:
                maxDay = 30;
                break;
            default:
                maxDay = 31;
                break;
        }

        if (day < 1 || day > maxDay) {
            return timeBucket;
        }

        if (dayStep <= 0) {
            return timeBucket;
        }

        // Compute the last day in the step period ending on or before 'day'
        long newDay = 1 + ((day - 1) / dayStep) * dayStep;
        if (newDay > maxDay) {
            newDay = maxDay;
        }

        long compressed = year * 10000 + month * 100 + newDay;
        return compressed;
    } catch (Exception e) {
        return timeBucket;
    }
}

