    }

    // Extract year, month, day from timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Create a calendar instance and set the initial date
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.set(year, month - 1, 1, 0, 0, 0);
    cal.set(java.util.Calendar.MILLISECOND, 0);

    // Get the time in milliseconds for the first day of the month
    long firstDayMillis = cal.getTimeInMillis();

    // Create a new calendar instance for the target date
    cal.set(year, month - 1, day, 0, 0, 0);
    cal.set(java.util.Calendar.MILLISECOND, 0);
    long targetDateMillis = cal.getTimeInMillis();

    // Calculate the number of days from the first of the month to the target date
    long daysFromStart = (targetDateMillis - firstDayMillis) / (24 * 60 * 60 * 1000);

    // Determine which dayStep period the target date falls into
    int periodStartDay = (int) (daysFromStart / dayStep) * dayStep + 1;

    // Adjust if the period start day exceeds the number of days in the month
    java.util.Calendar checkCal = java.util.Calendar.getInstance();
    checkCal.set(year, month - 1, 1, 0, 0, 0);
    int daysInMonth = checkCal.getActualMaximum(java.util.Calendar.DAY_OF_MONTH);
    if (periodStartDay > daysInMonth) {
        periodStartDay = daysInMonth - (int)((daysInMonth - periodStartDay) % dayStep) + 1;
        // Simplified approach: just use the target date
        periodStartDay = day;
    }

    return (long) year * 10000 + (long) month * 100 + periodStartDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive and in YYYYMMDD format");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    if (month < 1 || month > 12 || day < 1) {
        throw new IllegalArgumentException("Invalid timeBucket format: " + timeBucket);
    }

    long firstDayOfMonth = year * 10000 + month * 100 + 1;
    long offset = day - 1;
    long dayPart = 1 + (offset / dayStep) * dayStep;

    long monthsInYear = 12;
    long lastDayOfMonth;
    if (month == 2) {
        // Leap year check
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            lastDayOfMonth = 29;
        } else {
            lastDayOfMonth = 28;
        }
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        lastDayOfMonth = 30;
    } else {
        lastDayOfMonth = 31;
    }

    if (dayPart > lastDayOfMonth) {
        dayPart = lastDayOfMonth;
    }

    return year * 10000 + month * 100 + dayPart;
