public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final int len = str.length();
    int pos = 0;
    while (pos < len) {
        char c = str.charAt(pos);
        if (c < 0x80) { // ASCII
            lb.writeByte((byte) c);
            pos++;
        } else if (c < 0x800) { // 2 byte sequence
            lb.writeByte((byte) (0xC0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
            pos++;
        } else if (c < 0xD800 || c > 0xDBFF) { // 3 byte sequence, not a surrogate
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
            pos++;
        } else if (c > 0xDBFF) { // Invalid surrogate or unpaired high surrogate
            lb.writeByte((byte) 0xEF);
            lb.writeByte((byte) 0xBF);
            lb.writeByte((byte) 0xBD);
            pos++;
        } else { // High surrogate, expect low surrogate next
            if (pos + 1 < len) {
                char low = str.charAt(pos + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) { // Valid low surrogate
                    int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
                    lb.writeByte((byte) (0xF0 | (codePoint >> 18)));
                    lb.writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
                    lb.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
                    lb.writeByte((byte) (0x80 | (codePoint & 0x3F)));
                    pos += 2;
                } else { // No low surrogate follows
                    lb.writeByte((byte) 0xEF);
                    lb.writeByte((byte) 0xBF);
                    lb.writeByte((byte) 0xBD);
                    pos++;
                }
            } else { // No low surrogate follows (end of string)
                lb.writeByte((byte) 0xEF);
                lb.writeByte((byte) 0xBF);
                lb.writeByte((byte) 0xBD);
                pos++;
            }
        }
    }
    return lb;
}

