    }
    int len = str.length();
    byte[] buf = new byte[len * 3];
    int pos = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buf[pos++] = (byte) c;
        } else if (c < 0x800) {
            buf[pos++] = (byte) (0xC0 | (c >> 6));
            buf[pos++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c > 0xDFFF) {
            buf[pos++] = (byte) (0xE0 | (c >> 12));
            buf[pos++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buf[pos++] = (byte) (0x80 | (c & 0x3F));
        } else {
            if (c < 0xDC00) {
                // Surrogate pair
                int next = i + 1;
                if (next >= len) {
                    // Invalid surrogate
                    buf[pos++] = (byte) 0xEF;
                    buf[pos++] = (byte) 0xBF;
                    buf[pos++] = (byte) 0xBD;
                } else {
                    char low = str.charAt(next);
                    if (low >= 0xDC00 && low <= 0xDFFF) {
                        int cp = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
                        buf[pos++] = (byte) (0xF0 | (cp >> 18));
                        buf[pos++] = (byte) (0x80 | ((cp >> 12) & 0x3F));
                        buf[pos++] = (byte) (0x80 | ((cp >> 6) & 0x3F));
                        buf[pos++] = (byte) (0x80 | (cp & 0x3F));
                        i++;
                    } else {
                        // Invalid surrogate
                        buf[pos++] = (byte) 0xEF;
                        buf[pos++] = (byte) 0xBF;
                        buf[pos++] = (byte) 0xBD;
                    }
                }
            } else {
                // Lone low surrogate
                buf[pos++] = (byte) 0xEF;
                buf[pos++] = (byte) 0xBF;
                buf[pos++] = (byte) 0xBD;
            }
        }
    }
    session.buffer(lb, buf, 0, pos);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }

    final int length = str.length();
    int pos = 0;
    int startOffset = 0;

    while (pos < length) {
        char c = str.charAt(pos);
        if (c < 0x80) {
            // ASCII character, can encode directly
            // Check if there's enough space in the current chunk
            int bytesNeeded = 1;
            if (session.hasSpace(lb, bytesNeeded)) {
                session.writeByte(lb, (byte) c);
                pos++;
            } else {
                // Not enough space, write what we can
                break;
            }
        } else if (c < 0x800) {
            // Two-byte sequence
            int bytesNeeded = 2;
            if (session.hasSpace(lb, bytesNeeded)) {
                session.writeByte(lb, (byte) (0xC0 | (c >> 6)));
                session.writeByte(lb, (byte) (0x80 | (c & 0x3F)));
                pos++;
            } else {
                break;
            }
        } else if (c < 0xD800 || c > 0xDFFF) {
            // Three-byte sequence (non-surrogate)
            int bytesNeeded = 3;
            if (session.hasSpace(lb, bytesNeeded)) {
                session.writeByte(lb, (byte) (0xE0 | (c >> 12)));
                session.writeByte(lb, (byte) (0x80 | ((c >> 6) & 0x3F)));
                session.writeByte(lb, (byte) (0x80 | (c & 0x3F)));
                pos++;
            } else {
                break;
            }
        } else {
            // Surrogate pair handling
            if (c >= 0xD800 && c <= 0xDBFF) {
                // High surrogate, check if next char is a low surrogate
                if (pos + 1 < length) {
                    char low = str.charAt(pos + 1);
                    if (low >= 0xDC00 && low <= 0xDFFF) {
                        int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
                        int bytesNeeded = 4;
                        if (session.hasSpace(lb, bytesNeeded)) {
                            session.writeByte(lb, (byte) (0xF0 | (codePoint >> 18)));
                            session.writeByte(lb, (byte) (0x80 | ((codePoint >> 12) & 0x3F)));
                            session.writeByte(lb, (byte) (0x80 | ((codePoint >> 6) & 0x3F)));
                            session.writeByte(lb, (byte) (0x80 | (codePoint & 0x3F)));
                            pos += 2;
                        } else {
                            break;
                        }
                    } else {
                        // Invalid surrogate, skip high surrogate
                        pos++;
                    }
                } else {
                    // Unpaired high surrogate at end, skip
                    pos++;
                }
            } else {
                // Lone low surrogate, skip
                pos++;
            }
        }
    }

    return lb;
}

