private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }
    int suffixLength = suffix.length();
    int strLength = str.length();
    if (suffixLength > strLength) {
        return false;
    }
    if (ignoreCase) {
        for (int i = 0; i < suffixLength; i++) {
            char c1 = str.charAt(strLength - suffixLength + i);
            char c2 = suffix.charAt(i);
            if (c1 != c2 && Character.toLowerCase(c1) != Character.toLowerCase(c2)) {
                return false;
            }
        }
    } else {
        for (int i = 0; i < suffixLength; i++) {
            char c1 = str.charAt(strLength - suffixLength + i);
            char c2 = suffix.charAt(i);
            if (c1 != c2) {
                return false;
            }
        }
    }
    return true;
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return (str == null && suffix == null);
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    int diff = str.length() - suffix.length();
    if (ignoreCase) {
        return str.regionMatches(true, diff, suffix, 0, suffix.length());
    }
    return str.regionMatches(diff, suffix, 0, suffix.length());
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return (str == null && suffix == null);
    }
    if (ignoreCase) {
        int caseStr = str.toLowerCase().length();
        int caseSuffix = suffix.toLowerCase().length();
        if (caseStr < caseSuffix) {
            return false;
        }
        return str.regionMatches(true, caseStr - caseSuffix, suffix, 0, caseSuffix);
    }
    if (str.length() < suffix.length()) {
        return false;
    }
    return str.endsWith(suffix);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        return null;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }

    List<String> segments;
    if (path.startsWith("/")) {
        path = path.substring(1);
        segments = new ArrayList<>(Arrays.asList(path.split("/")));
    } else {
        segments = new ArrayList<>(Arrays.asList(path.split("/")));
    }

    List<PathSegmentImpl> result = new ArrayList<>();
    for (String segment : segments) {
        if (!segment.isEmpty()) {
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    // UTF-8 is always supported
                }
            }
            result.add(new PathSegmentImpl(segment));
        }
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<PathSegmentImpl>();
    if (u == null || u.getPath() == null) {
        return result;
    }
    String path = u.getPath();
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return result;
    }
    String[] segments = path.split("/", -1);
    for (String segment : segments) {
        if (decode) {
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        result.add(new PathSegmentImpl(segment));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u != null && u.getPath() != null) {
        String path = u.getPath();
        if (!path.isEmpty()) {
            // Split by '/', ignoring leading '/' as it's not a segment delimiter
            String[] parts = path.replaceAll("^/", "").split("/");
            for (String part : parts) {
                if (part.isEmpty()) {
                    continue;
                }
                if (decode) {
                    try {
                        part = URLDecoder.decode(part, "UTF-8");
                    } catch (UnsupportedEncodingException e) {
                        // UTF-8 is always supported, but this can still happen in rare edge cases
                    }
                }
                segments.add(new PathSegmentImpl(part));
            }
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> rawSegments = PathSegmentImpl.segmentsFromPath(u.getPath());
    if (decode) {
        List<PathSegmentImpl> decoded = new ArrayList<PathSegmentImpl>();
        for (PathSegmentImpl segment : rawSegments) {
            decoded.add(new PathSegmentImpl(decodeValue(segment.getValue())));
        }
        return decoded;
    }
    return rawSegments;
}

public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
    List<PathSegmentImpl> path = new LinkedList<PathSegmentImpl>();
    if ( u == null )
        return path;
    String pathString = u.getRawPath();
    if ( pathString == null )
        return path;
    int start = 0;
    if ( pathString.startsWith( "/" ) )
        start = 1;
    if ( start == pathString.length() )
        return path;
    int end = pathString.indexOf( '/', start );
    while ( end != -1 )
    {
        String pathSegment = pathString.substring( start, end );
        PathSegmentImpl segment = new PathSegmentImpl( pathSegment );
        if ( decode )
            segment.decode();
        path.add( segment );
        start = end + 1;
        end = pathString.indexOf( '/', start );
    }

    // handle the last path segment
    String pathSegment = pathString.substring( start );
    PathSegmentImpl segment = new PathSegmentImpl( pathSegment );
    if ( decode )
        segment.decode();
    path.add( segment );
    return path;
}

