public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (shift < 64) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new InvalidProtocolBufferException("Data exceeding 64 bits");
}

public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        if (shift == 64) {
            break;
        }
        long b = readRawVarintByte();
        result |= (b & 0x7FL) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    return result;
}

public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (shift < 64) {
        byte b = (byte) in.readByte();
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    if (shift == 64) {
        // Check for overflow.
        byte b = (byte) in.readByte();
        if ((b & 0x7F) != 0) {
            throw new IOException("CodedInputStream was exhausted before varint was complete");
        }
    }
    return result;
}

