public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
double left = box.getX(); 
double right = box.getX() + box.getWidth(); 
double middle = (left + right) / 2.0; 
Box2D leftBox = new Box2D(left, box.getY(), ( right  - left) / 2.0, box.getHeight()); 
Box2D rightBox = new Box2D(middle, box.getY(), ( right  - left) / 2.0, box.getHeight()); 
return new Pair<Box2D,Box2D>(leftBox, rightBox); 
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        return null;
    }
    double minx = box.getMinX();
    double maxx = box.getMaxX();
    double midx = minx + (maxx - minx) / 2.0;
    Box2D leftBox = new Box2D(minx, midx, box.getMinY(), box.getMaxY());
    Box2D rightBox = new Box2D(midx, maxx, box.getMinY(), box.getMaxY());
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double halfWidth = box.getWidth() / 2.0;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(box.getMinX() + halfWidth, box.getMinY(), halfWidth, box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    double x = box.x1 + ( box.x2 - box.x1 ) / 2 ;
    Box2D left = new Box2D ( box.x1 , x , box.y1 , box.y2 ) ;
    Box2D right = new Box2D ( x , box.x2 , box.y1 , box.y2 ) ;
    return new Pair < Box2D , Box2D > ( left , right ) ;
}

