@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == Character.TYPE) {
        if (value instanceof Character) {
            return (Character) value;
        }
        if (value instanceof Number) {
            return Character.valueOf((char) ((Number) value).intValue());
        }
        if (value instanceof String) {
            String strValue = ((String) value).trim();
            if (strValue.length() == 1) {
                return Character.valueOf(strValue.charAt(0));
            }
            throw new Exception("Cannot convert string to Character: " + strValue);
        }
        return Character.valueOf(value.toString().charAt(0));
    }
    return super.convertToType(type, value);
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) return null;
    if (type == CHAR_CLASS) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String strVal = (String) value;
            return (strVal.length() == 1) ? strVal.charAt(0) : null;
        } else if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        }
    }
    return value;
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
        if (type.isAssignableFrom(Character.class) || type.isAssignableFrom(char.class)) {
            if (value instanceof Number) {
                return Character.valueOf((char) (((Number) value).intValue()));
            }
            String strValue = getStrValue(value);
            if (strValue == null) return null;
            strValue = strValue.trim();
            if (strValue.length() != 1) throw new ConversionException(value.getClass().getName(), type.getName(), "strValue must be single character: [" + strValue + "]");
            return Character.valueOf(strValue.charAt(0));
        } else if (type.isAssignableFrom(String.class)) {
            if (value == null) return null;
            char charValue = convertToChar(value);
            return String.valueOf(charValue);
        } else return convertToType(type, value);
    }

