public static int nextPrime(int desiredCapacity) {
    int candidate = (int) (desiredCapacity * 1.1) + 1;
    while (!isPrime(candidate)) {
        candidate++;
    }
    return candidate;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        // Handle non-positive capacities by returning 0 or some minimum prime
        return 0; // or 2, depending on use case
    }

    int candidate = desiredCapacity;

    // Convert to an odd number if even (except for 2)
    if (candidate > 2 && (candidate % 2 == 0)) {
        candidate++;
    }

    // Check for primality
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        return 2;
    }
    for (int i = desiredCapacity; ; i++) {
        if (i < 2) {
            continue;
        }
        if (i % 2 == 0 && i != 2) {
            continue;
        }
        boolean isPrime = true;
        for (int j = 3; j * j <= i; j += 2) {
            if (i % j == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return i;
        }
    }
}

