@Override
public String readString() throws IOException {
    int high = read();
    if (high == -1) {
        throw new EOFException();
    }
    int len = high & 0x7f;
    if (high >= 0x80) {
        if (high >= 0xfc) {
            throw new IOException("Unknown length type " + Integer.toHexString(high));
        }
        low = len & 0x1f;
        int tempLen;
        switch (high & 0x1f) {
            case 1:
                break;
            case 2:
                tempLen = read();
                if (tempLen == -1) {
                    throw new EOFException();
                }
                len = (low << 8) + (tempLen & 0xff);
                break;
            case 3:
                tempLen = read();
                if (tempLen == -1) {
                    throw new EOFException();
                }
                low = tempLen & 0xff;
                tempLen = read();
                if (tempLen == -1) {
                    throw new EOFException();
                }
                len = (low << 8) + (tempLen & 0xff);
                break;
            case 4:
                throw new IOException("String length too large: " + Integer.toHexString(high));
        }
    }
    if (len != 0) {
        readFully(buf.array(), 0, len);
        return new String(buf.array(), 0, len, charset);
    }
    return "";
}

public String readString() throws IOException {
    StringBuilder sb = new StringBuilder();
    int c;
    while ((c = read()) != -1) {
        if (c == '"') {  // Assuming the field is enclosed in double quotes
            break;
        }
        sb.append((char) c);
    }
    return sb.toString();
}

