private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    if (jsonObject.has("ats")) {
        JsonElement atsElement = jsonObject.get("ats");
        if (atsElement.isJsonArray()) {
            List<String> atsList = new ArrayList<>();
            for (JsonElement element : atsElement.getAsJsonArray()) {
                if (element.isJsonObject()) {
                    JsonObject atsObj = element.getAsJsonObject();
                    if (atsObj.has("id")) {
                        atsList.add(atsObj.get("id").getAsString());
                    }
                }
            }
            content.put("ats", atsList);
        } else if (atsElement.isJsonArray()) {
            content.put("ats", new ArrayList<String>());
        }
    }
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        if (!"ats".equals(entry.getKey())) {
            String key = entry.getKey();
            JsonElement value = entry.getValue();
            if (value.isJsonPrimitive()) {
                if (value.getAsJsonPrimitive().isString()) {
                    content.put(key, value.getAsString());
                } else if (value.getAsJsonPrimitive().isNumber()) {
                    content.put(key, value.getAsNumber());
                } else {
                    content.put(key, value.getAsBoolean());
                }
            } else if (value.isJsonObject()) {
                content.put(key, buildContent(value.getAsJsonObject()));
            } else if (value.isJsonArray()) {
                List<Object> list = new ArrayList<>();
                for (JsonElement element : value.getAsJsonArray()) {
                    if (element.isJsonPrimitive()) {
                        if (element.getAsJsonPrimitive().isString()) {
                            list.add(element.getAsString());
                        } else if (element.getAsJsonPrimitive().isNumber()) {
                            list.add(element.getAsNumber());
                        } else {
                            list.add(element.getAsBoolean());
                        }
                    } else if (element.isJsonObject()) {
                        list.add(buildContent(element.getAsJsonObject()));
                    }
                }
                content.put(key, list);
            }
        }
    }
    return content;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        content.put(entry.getKey(), jsonStringify(entry.getValue()));
    }
    return content;
}

