public final byte[] toByteArray(){
    // Check if there are no buffers, return an empty array
    if (buffer == null || buffer.length == 0) {
        return new byte[0];
    }

    // Calculate the total size of all buffers
    int totalSize = 0;
    for (int i = 0; i < buffer.length; i++) {
        if (buffer[i] != null) {
            totalSize += buffer[i].remaining();
        }
    }

    // Create a byte array of the total size
    byte[] result = new byte[totalSize];
    int offset = 0;

    // Copy contents from each buffer
    for (int i = 0; i < buffer.length; i++) {
        if (buffer[i] != null && buffer[i].hasRemaining()) {
            int len = buffer[i].remaining();
            System.arraycopy(buffer[i].array(), buffer[i].position(), result, offset, len);
            offset += len;
            buffer[i].position(buffer[i].limit());
        }
    }

    return result;
}

