public final byte[] toByteArray() {
    if (buffers.length == 0) {
        return new byte[0];
    }
    int totalSize = 0;
    for (ByteBuffer buffer : buffers) {
        totalSize += buffer.remaining();
    }
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (ByteBuffer buffer : buffers) {
        int remaining = buffer.remaining();
        buffer.get(result, offset, remaining);
        offset += remaining;
    }
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    StringBuilder buf = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i == len - 1) {
                // unexpected end of string
                buf.append(ch);
            } else {
                char next = str.charAt(++i);
                switch (next) {
                    case 'b':
                        buf.append('\b');
                        break;
                    case 't':
                        buf.append('\t');
                        break;
                    case 'n':
                        buf.append('\n');
                        break;
                    case 'f':
                        buf.append('\f');
                        break;
                    case 'r':
                        buf.append('\r');
                        break;
                    case 'u':
                        if (i + 3 < len) {
                            char c1 = str.charAt(++i);
                            char c2 = str.charAt(++i);
                            char c3 = str.charAt(++i);
                            char c4 = str.charAt(++i);
                            buf.append((char) ((c1 << 12) | (c2 << 8) | (c3 << 4) | c4));
                        } else {
                            // malformed unicode escape, just copy the characters
                            buf.append('\\');
                            buf.append('u');
                            buf.append(c1);
                            buf.append(c2);
                            buf.append(c3);
                            buf.append(c4);
                        }
                        break;
                    case '"':
                        buf.append('"');
                        break;
                    case '\'':
                        buf.append('\'');
                        break;
                    case '\\':
                        buf.append('\\');
                        break;
                    default:
                        // unknown escape, just keep the backslash and the following char
                        buf.append('\\');
                        buf.append(next);
                        break;
                }
            }
        } else {
            buf.append(ch);
        }
    }
    return buf.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder ret = new StringBuilder(str.length());
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            String nows = str.substring(i);
            if (nows.startsWith("\\n")) {
                ret.append('\n');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\t")) {
                ret.append('\t');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\r")) {
                ret.append('\r');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\f")) {
                ret.append('\f');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\b")) {
                ret.append('\b');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\\"")) {
                ret.append('"');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\'")) {
                ret.append('\'');
                i += 2;
                continue;
            }
            if (nows.startsWith("\\\\")) {
                ret.append('\\');
                i += 2;
                continue;
            }
            String s2 = nows.substring(0, 4);
            if (s2.matches("\\\\u[0-9a-fA-F]{4}")) {
                ret.append((char) Long.parseLong(nows.substring(2, 6), 16));
                i += 6;
                continue;
            }
        }
        ret.append(c);
        i++;
    }
    return ret.toString();
}

private static String javaCharset(String charset) {
    if (charset == null) {
        return null;
    }
    switch (charset.toLowerCase()) {
        case "us-ascii":
        case "iso-8859-1":
        case "iso8859-1":
            return "iso-8859-1";
        case "iso-8859-2":
        case "iso8859-2":
            return "iso-8859-2";
        case "iso-8859-3":
        case "iso8859-3":
            return "iso-8859-3";
        case "iso-8859-4":
        case "iso8859-4":
            return "iso-8859-4";
