final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int nameIndex = classFileBuffer.getInt(constantPoolEntryIndex - 4);
    int offset = nameIndex - 4;
    int length = classFileBuffer.getShort(offset);
    int start = offset + 2;
    int end = start + length;
    try {
        byte[] bytes = classFileBuffer.getBytes(start, length);
        int i = 0;
        while (i < length) {
            int b1 = bytes[i] & 0xFF;
            if (b1 < 0x80) {
                charBuffer[i++] = (char) b1;
            } else if ((b1 & 0xE0) == 0xC0) {
                int b2 = bytes[i + 1] & 0x3F;
                charBuffer[i] = (char) (((b1 & 0x1F) << 6) | b2);
                i += 2;
            } else if ((b1 & 0xF0) == 0xE0) {
                int b2 = bytes[i + 1] & 0x3F;
                int b3 = bytes[i + 2] & 0x3F;
                charBuffer[i] = (char) (((b1 & 0x0F) << 12) | (b2 << 6) | b3);
                i += 3;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding");
            }
        }
        return new String(charBuffer, 0, length);
    } catch (Exception e) {
        throw new RuntimeException("Error reading UTF-8 constant", e);
    }
