    // We should not cache the position of the constant pool buffer since it may be read by other threads
    // or it may be in a different position due to prior reads
    int size = classFileBuffer.getShort(constantPoolEntryIndex) & 0xFFFF;
    if (size > charBuffer.length) {
        throw new IllegalArgumentException("the buffer is not large enough");
    }
    int len = 0;
    for (int i = 0; i < size && classFileBuffer.get(constantPoolEntryIndex + 2 + i) != 0; i++) {
        charBuffer[len++] = (char) (classFileBuffer.get(constantPoolEntryIndex + 2 + i) & 0xFF);
    }
    return new String(charBuffer, 0, len);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= constantPool.endEntry) {
        throw new IllegalStateException("Invalid constant pool index: " + constantPoolEntryIndex);
    }

    classFileBuffer.position(constantPool.entryStart + constantPool.entrySizes[constantPoolEntryIndex]);

    // Read the constant type byte
    int constantType = classFileBuffer.get() & 0xFF;
    if (constantType != CONSTANT_Utf8) {
        throw new IllegalArgumentException("Invalid constant type: expected CONSTANT_Utf8 but got " + constantType);
    }

    // Read the UTF8 string length
    int length = readUShort(classFileBuffer);

    // Check that the buffer is large enough to hold the decoded string
    // The maximum number of characters resulting from decoding could be up to 'length'
    // (in the worst case, each byte decodes to one char), so we need at least 'length' chars
    if (charBuffer == null || charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer is not large enough to hold the decoded UTF8 string");
    }

    int numChars = decodeUtf8(classFileBuffer, charBuffer, length);

    return new String(charBuffer, 0, numChars);
