public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength == 0) {
        return this;
    }
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative: " + byteLength);
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset must be non-negative: " + byteOffset);
    }
    if (byteArrayValue == null) {
        if (byteOffset != 0) {
            throw new IllegalArgumentException("byteOffset must be zero for a null array: " + byteOffset);
        }
        if (byteLength > this.length - 0) {
            throw new IllegalArgumentException("byteLength exceeds remaining space");
        }
        final int currentLength = this.length;
        final int newLength = currentLength + byteLength;
        if (newLength > data.length) {
            enlarge(byteLength);
        }
        for (int i = 0; i < byteLength; ++i) {
            data[currentLength + i] = 0;
        }
        this.length = newLength;
        return this;
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("byteOffset + byteLength exceeds array length");
    }
    final int currentLength = this.length;
    if (currentLength + byteLength > data.length) {
        enlarge(byteLength);
    }
