protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new GraphPath<>();
    }

    // Build adjacency information from the tour edges
    Map<V, Map<V, E>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V src = graph.getEdgeSource(edge);
        V tgt = graph.getEdgeTarget(edge);

        adjacency.computeIfAbsent(src, k -> new HashMap<>()).put(tgt, edge);
        adjacency.computeIfAbsent(tgt, k -> new HashMap<>()).put(src, edge);
    }

    // Find the start node (a node with degree 2, pick any)
    V start = null;
    for (V node : adjacency.keySet()) {
        start = node;
        break;
    }

    // Traverse the tour starting from the start node
    List<E> order = new ArrayList<>();
    V current = start;
    V previous = null;

    while (true) {
        Map<V, E> neighbors = adjacency.get(current);
        if (neighbors == null || neighbors.isEmpty()) {
            break;
        }

        V next = null;
        E edge = null;
        for (Map.Entry<V, E> entry : neighbors.entrySet()) {
            if (!entry.getKey().equals(previous)) {
                next = entry.getKey();
                edge = entry.getValue();
                break;
            }
        }

        if (edge == null) {
            // All neighbors are previous, we should have completed the circuit
            break;
        }

        order.add(edge);
        previous = current;
        current = next;

        // If we've visited all edges, stop
        if (order.size() == tour.size()) {
            break;
        }

        // If we're back to start, also stop
        if (current.equals(start)) {
            break;
        }
    }

    return new GraphPath<>(order);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph cannot be null");
    }

    // Create adjacency list representation from the set of edges
    Map<V, Map<V, Set<E>>> adjacencyList = new HashMap<>();

    for (E edge : tour) {
        V from = graph.getEdgeSource(edge);
        V to = graph.getEdgeTarget(edge);

        adjacencyList.computeIfAbsent(from, k -> new HashMap<>())
                .computeIfAbsent(to, k -> new HashSet<>())
                .add(edge);
    }

    // Find the start node (a node with outgoing edges)
    V startNode = null;
    for (V v : adjacencyList.keySet()) {
        if (!adjacencyList.get(v).isEmpty()) {
            startNode = v;
            break;
        }
    }

    if (startNode == null) {
        return new GraphPath<>(graph);
    }

    // Build the path
    List<VertexPath.Episode<V,E>> episodes = new ArrayList<>();
    V current = startNode;
    Set<E> usedEdges = new HashSet<>(tour);
    int maxSteps = tour.size() + 1;
    int step = 0;

    while (step < maxSteps) {
        // Find next edge from current node
        Iterator<Map.Entry<V, Set<E>>> neighborIterator = adjacencyList.get(current).entrySet().iterator();
        V next = null;
        E nextEdge = null;
        while (neighborIterator.hasNext()) {
            Map.Entry<V, Set<E>> entry = neighborIterator.next();
            if (entry.getValue().isEmpty()) {
                continue;
            }
            Iterator<E> edgeIterator = entry.getValue().iterator();
            if (edgeIterator.hasNext()) {
                next = entry.getKey();
                nextEdge = edgeIterator.next();
                if (usedEdges.remove(nextEdge)) {
                    entry.getValue().remove(nextEdge);
                    break;
                }
            }
        }

        if (next == null || next.equals(startNode)) {
            break;
        }

        episodes.add(new VertexPath.Episode<>(current, next, nextEdge));
        current = next;
        step++;
    }

    GraphPath<V,E> path = new GraphPath<>(graph);
    for (VertexPath.Episode<V,E> episode : episodes) {
        path.addEpisode(episode);
    }

    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // If the tour is empty, return an empty path
    if (tour.isEmpty()) {
        return GraphPath.empty();
    }

    // Find a starting edge and node
    E firstEdge = tour.iterator().next();
    V start = graph.getFatherVertex(firstEdge);
    if (start == null) {
        start = graph.getMotherVertex(firstEdge);
    }

    // Build the path
    List<VertexPair<V, E>> pathBuilder = new ArrayList<>();
    Set<V> visitedNodes = new HashSet<>();
    Set<E> visitedEdges = new HashSet<>();
    visitedNodes.add(start);
    visitedEdges.add(firstEdge);
    pathBuilder.add(new VertexPair<>(start, firstEdge));

    V current = graph.getSonVertex(firstEdge);
    if (current == null) {
        current = graph.getFatherVertex(firstEdge);
    }

    // Keep adding edges until we return to the start
    while (current != null && !current.equals(start) && visitedEdges.size() < tour.size()) {
        visitedNodes.add(current);

        // Find an unvisited edge incident to the current node
        E nextEdge = null;
        for (E e : graph.getIncidentEdges(current)) {
            if (!visitedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            // If no outgoing edge found, try revisiting logic or handle error
            // For a valid tour, this should not happen unless the tour structure is broken
            break;
        }

        visitedEdges.add(nextEdge);
        V nextNode = graph.getSonVertex(nextEdge);
        if (nextNode == null) {
            nextNode = graph.getFatherVertex(nextEdge);
        }

        pathBuilder.add(new VertexPair<>(current, nextEdge));
        current = nextNode;
    }

    // If the tour isn't closed properly or something went wrong, 
    // we might need to handle it, but assuming valid input for standard tours.

    return new GraphPath<>(pathBuilder, start);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    GraphPath<V,E> path = new SGraphPath<V,E>();
    int numEdges = tour.size();
    if (numEdges == 0) {
        return path;
    }

    // Hopcroft-Tarjan (or some heuristics) can be used to tighten tours, see
    // http://cs-people.bu.edu/herb/so/tsp.html

    Map<V, V[]> checkPositions = new HashMap<V, V[]>(numEdges);
    Map<E, V[]> pairedEdges = new HashMap<E, V[]>(numEdges);

    // start with an arbitrary vertex
    V v;

    Set<E> remainingEdges = new HashSet<E>(tour);
    for (E edge : tour) {
        V[] vertices = Utils.getVAndW(edge, graph);
        // choose an odd-degree vertex
        int degree = graph.degree(vertices[0]);
        if (degree % 2 != 0) {
            v = vertices[0];
        }
    }

    for (V temp : graph.getVertices()) {
        if (degree < graph.degree(temp)) {
            v = temp;
        }
    }

    // System.out.println("odd degree vertex : " + v);

    remainingEdges = new HashSet<E>(tour);
    while (v != null) {
        // find an edge adjacent to v
        V[] vertices = null;
        for (E edge : graph.incidentEdges(v)) {
            if (!tour.contains(edge)) {
                continue;
            }
            vertices = Utils.getVAndW(edge, graph);
            break;
        }
        /*
         * A second search for the optimal edge can be added here. Branch
         * and bound is used now.
         */
        boolean hasFollow = false;
        for (V neighbor : graph.getNeighbors(v)) {
            if (!remainingEdges.contains(graph.getEdge(v, neighbor))) {
                continue;
            }
            int eSquared = getEdgeCost(edge, graph);
            int diff = eSquared - getEdgeCost(graph.getEdge(v, neighbor), graph);
            if (diff < 0) {
                edge = graph.getEdge(v, neighbor);
                hasFollow = true;
            }
        }

        if (hasFollow == false) {
            if (remainingEdges.isEmpty()) {
                break;
            }
            throw new IllegalStateException("Could not find adjacency");
        }

        if (vertices[0].equals(v)) {
            path.addPath(name + " step start" + " path to " + vertices[1]);
        } else {
            path.addPath(vertices[1]);
        }

        remainingEdges.remove(edge);
        v = vertices[0].equals(v) ? vertices[1] : vertices[0];
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    Map<V, Set<V>> visited = new HashMap<>();
    for (V v : graph.getVertices()) {
        visited.put(v, new HashSet<>());
    }
    V start = null;
    V prev = null;
    for (E edge : tour) {
        V u = graph.getEdgeSource(edge);
        V v = graph.getEdgeTarget(edge);
        if (visited.get(u).isEmpty()) {
            if (visited.get(v).size() == 1) {
                start = v;
            } else {
                start = u;
            }
            prev = null;
            break;
        }
    }
    List<V> tourList = new ArrayList<>();
    V current = start;
    tourList.add(current);
    while (visited.get(current).size() < 2) {
        for (V next : graph.getNeighbors(current)) {
            if (!visited.get(current).contains(next)) {
                visited.get(current).add(next);
                visited.get(next).add(current);
                current = next;
                tourList.add(current);
                break;
            }
        }
        if (visited.get(current).size() == 2) {
            break;
        }
    }
    // Reconstruct the tour properly by following edges
    Map<E, V> edgeTo = new HashMap<>();
    for (E edge : tour) {
        V u = graph.getEdgeSource(edge);
        V v = graph.getEdgeTarget(edge);
    }

    List<V> path = new ArrayList<>();
    V node = start;
    path.add(node);
    while (path.size() < tour.size() + 1) {
        V nextNode = null;
        for (V v : graph.getNeighbors(node)) {
            boolean edgeInTour = false;
            for (E edge : tour) {
                V u = graph.getEdgeSource(edge);
                V w = graph.getEdgeTarget(edge);
                if ((u.equals(node) && w.equals(v)) || (u.equals(v) && w.equals(node))) {
                    edgeInTour = true;
                    break;
                }
            }
            if (edgeInTour && !path.contains(v)) {
                nextNode = v;
                break;
            }
        }
        if (nextNode == null) {
            for (V v : graph.getNeighbors(node)) {
                boolean edgeInTour = false;
                for (E edge : tour) {
                    V u = graph.getEdgeSource(edge);
                    V w = graph.getEdgeTarget(edge);
                    if ((u.equals(node) && w.equals(v)) || (u.equals(v) && w.equals(node))) {
                        edgeInTour = true;
                        break;
                    }
                }
                if (edgeInTour) {
                    nextNode = v;
                    break;
                }
            }
        }
        if (nextNode == null) break;
        path.add(nextNode);
        node = nextNode;
    }
    EdgeIterableGraph<V,E> edgeIterableGraph = new EdgeIterableGraph<>(graph);
    return new GraphPathImpl<>(edgeIterableGraph, path);
}

