private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        return;
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }

    Set<Integer> targetBucket = bucketsByLabel.get(0);

    // Move all vertices from the minLabel bucket to the bucket with label 0
    for (Integer vertex : minBucket) {
        labels.set(vertex, 0);  // Update the label of the vertex to 0
        targetBucket.add(vertex);  // Add the vertex to the target bucket
    }

    // Clear the bucket with label minLabel
    minBucket.clear();
}

