                        String endSeq = sequenceNumbers.get(endIndex);
                        SequenceRange range = new SequenceRange();
                        range.setStartingSequenceNumber(startSeq);
                        range.setEndingSequenceNumber(endSeq);
                        sequenceRanges.add(range);
                    }
                }
            }
        }
    }
    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    for (ProfilesSegmentSnapshot snapshot : snapshots) {
        String startingSequenceNumber = snapshot.getStartingSequenceNumber();
        String endingSequenceNumber = snapshot.getEndingSequenceNumber();
        if (startingSequenceNumber != null && endingSequenceNumber != null) {
            SequenceRange range = new SequenceRange(startingSequenceNumber, endingSequenceNumber);
            sequenceRanges.add(range);
        }
    }
    return sequenceRanges;
}

