private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(bounds.size(), 0));
    long total = 0L;
    long runningSum = 0L;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffixSum.set(i, (int) runningSum);
    }

    total = runningSum;

    return Pair.of(suffixSum, total);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    Objects.requireNonNull(bounds, "bounds must not be null");

    List<Integer> suffixSums = new ArrayList<>();
    long totalSum = 0;

    // First, calculate the total sum and initialize suffix sums with 0
    for (Integer b : bounds) {
        totalSum += b;
        suffixSums.add(0); // Placeholder
    }

    // Compute suffix sums from the end
    int n = bounds.size();
    for (int i = n - 1; i >= 0; i--) {
        // suffix sum at i is bounds[i] + ... + bounds[n-1]
        // We can compute it as totalSum - (sum of elements before i)
        // But easier: maintain a running sum from the right
        if (i == n - 1) {
            suffixSums.set(i, bounds.get(i));
        } else {
            suffixSums.set(i, bounds.get(i) + suffixSums.get(i + 1));
        }
    }

    // The sum of all elements is totalSum; pair with suffixSums list
    return new Pair<>(suffixSums, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0;

    // Calculate total sum
    for (int value : bounds) {
        totalSum += value;
    }

    // Calculate suffix sum
    suffixSum.set(n - 1, bounds.get(n - 1));
    for (int i = n - 2; i >= 0; i--) {
        suffixSum.set(i, bounds.get(i) + suffixSum.get(i + 1));
    }

    return Pair.of(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;
    long suffix = 0;

    // Compute sum of all elements
    for (Integer num : bounds) {
        sum += num;
    }

    // Compute suffix sums from the end
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffix += bounds.get(i);
        suffixSum.add((int) suffix);
    }

    // Reverse to get correct order (suffix sum for each position)
    Collections.reverse(suffixSum);

    return new Pair<>(suffixSum, sum);
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    ListNode<E> node = list.head;// the node to be transferred, start from the head
    while (node != null) {
        ListNode<E> next = node.next;// the next node to be transferred
        list.removeListNode(node);// remove the node from the original list
        this.addListNode(node);// add the node to this list
        node = next;
    }
}

