private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    if (graph == null) {
        return Collections.emptyList();
    }
    List<Pair<List<Pair<Integer,Integer>>, E>> result = new ArrayList<>();
    for (E edge : graph.edges()) {
        Integer source = graph.first(edge);
        Integer target = graph.second(edge);
        if (source == null || target == null) {
            continue;
        }
        List<Pair<Integer, Integer>> neighborhoodSeparators = computeMinimalSeparatorsInNeighborhood(source, target);
        result.add(new Pair<>(neighborhoodSeparators, edge));
    }
    return result;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> result = new ArrayList<>(this.graph.sizeE());
    for (E edge : this.graph.getEdges()) {
        Pair<Integer, Integer> edgeEnds = new Pair<>(this.graph.edgeEnd0(edge), this.graph.edgeEnd1(edge));
        List<Pair<Integer,Integer>> neighborhood = new ArrayList<>(this.graph.graph.sizeE());
        for (E neigh : this.graph.getEdges(edge))
            if (!this.graph.hasEdge(neigh, edgeEnds))
                neighborhood.add(new Pair<>(this.graph.edgeEnd0(neigh), this.graph.edgeEnd1(neigh)));
        for (List<Pair<Integer,Integer>> minimalSeparator : this.algorithms.neighborhoodSplitter().computeEdgeStubbing(neighborhood))
            result.add(new Pair<>(minimalSeparator, edge));
    }
    return result;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer, Integer>> separatorsForEdge = new ArrayList<>();
        int u = graph.getVertexOfEdge(e, 0);
        int v = graph.getVertexOfEdge(e, 1);
        Set<Integer> neighborsOfU = graph.getNeighbors(u);
        Set<Integer> neighborsOfV = graph.getNeighbors(v);
        neighborsOfU.remove(v);
        neighborsOfV.remove(u);
        Set<Integer> commonNeighbors = new HashSet<>(neighborsOfU);
        commonNeighbors.retainAll(neighborsOfV);
        if (commonNeighbors.isEmpty()) {
            continue;
        }
        List<Integer> neighborsList = new ArrayList<>(commonNeighbors);
        for (int i = 0; i < neighborsList.size(); i++) {
            for (int j = i + 1; j < neighborsList.size(); j++) {
                int a = neighborsList.get(i);
                int b = neighborsList.get(j);
                separatorsForEdge.add(new Pair<>(a, b));
            }
        }
        globalSeparatorList.add(new Pair<>(separatorsForEdge, e));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    // Get all edges from the graph
    Iterable<E> edges = getGraph().getEdges();

    for (E edge : edges) {
        // For each edge, compute the local separators (minimal separators in the neighborhood of the edge)
        List<List<Pair<Integer,Integer>>> localSeparators = computeLocalSeparatorList(edge);

        // Add each local separator with the edge to the global list
        for (List<Pair<Integer,Integer>> separator : localSeparators) {
            globalSeparatorList.add(new Pair<>(separator, edge));
        }
    }

    return globalSeparatorList;
}

