private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int left = 0;
        int right = i;
        K key = keys.get(i);
        int result = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (compare(keys.get(mid), key) <= 0) {
                result = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        lowerBounds.add(result);
    }
    return lowerBounds;
}

