public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return path;
    }

    // Normalize the runtime OS path using '/' separators
    // Find the last '/' in the path to get the directory part
    int lastSlashIndex = path.lastIndexOf('/');
    if (lastSlashIndex == -1) {
        // No directory part, path is just a file name
        return relativePath;
    }

    String directory = path.substring(0, lastSlashIndex);
    if (directory.isEmpty()) {
        // Path is like /file, directory is /
        return "/" + relativePath;
    }

    // Join directory and relativePath with '/'
    return directory + "/" + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    try {
        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("path and relativePath must not be null");
        }

        // Get the base directory (parent) of the given path.
        // We assume the path ends with a filename, so we need to go up one level
        // to get the directory, then apply the relative path.
        // However, "apply relative path" usually means: take the path, if it's a file,
        // go to its parent dir, then apply the relative path. Or it could mean
        // path + relativePath treating path as a directory.

        // Let's look at the description: "Apply the given relative path to the given path"
        // "usually a full file path" and "relative to the full file path above".
        // If path is /a/b/c.txt and relativePath is /d.txt, 
        // and we treat path as a directory, result is /a/b/c.txt/d.txt (wrong)
        // If we treat path as a file, parent is /a/b, result is /a/b/d.txt.

        // Let's assume the standard behavior: 
        // If path is a full file path, we resolve relative to its parent directory.

        int lastSlash = path.lastIndexOf('/');
        String baseDir;
        if (lastSlash == 0) {
            baseDir = "/";
        } else if (lastSlash > 0) {
            baseDir = path.substring(0, lastSlash);
        } else {
            baseDir = ""; // path is just a filename like "file.txt"
        }

        // Now resolve baseDir + relativePath
        // Handle ".." and "." in relativePath
        String[] baseParts = baseDir.isEmpty() ? new String[]{} : baseDir.split("/");
        String[] relParts = relativePath.split("/");

        LinkedList<String> result = new LinkedList<String>();

        for (String part : baseParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (!result.isEmpty()) {
                    result.removeLast();
                }
            } else {
                result.addLast(part);
            }
        }

        // Determine if baseDir was absolute
        boolean absolute = baseDir.startsWith("/") || path.startsWith("/");

        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (!result.isEmpty()) {
                    result.removeLast();
                } else if (absolute) {
                    // Can't go above root
                    continue;
                }
            } else {
                result.addLast(part);
            }
        }

        String pathStr;
        if (result.isEmpty()) {
            pathStr = absolute ? "/" : ".";
        } else {
            StringBuilder sb = new StringBuilder();
            if (absolute) {
                sb.append("/");
            }
            for (int i = 0; i < result.size(); i++) {
                if (i > 0) {
                    sb.append("/");
                }
                sb.append(result.get(i));
            }
            pathStr = sb.toString();
        }

        return pathStr;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

