static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return null;
    }

    // First check if there are any null elements
    boolean hasNull = false;
    int count = 0;
    for (Object obj : array) {
        if (obj == null) {
            hasNull = true;
        } else {
            count++;
        }
    }

    if (!hasNull) {
        // No nulls, convert to String[] and return
        String[] result = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = (String) array[i];
        }
        return result;
    }

    // Filter out nulls
    String[] result = new String[count];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[index++] = (String) obj;
        }
    }

    return result;
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    // Count nulls
    int nullCount = 0;
    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        }
    }
    // If no nulls, return original
    if (nullCount == 0) {
        return (String[]) array;
    }
    // Create new array and exclude nulls, copying by checking each element
    int newSize = array.length - nullCount;
    String[] newArray = new String[newSize];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            newArray[index++] = (String) obj;
        }
    }
    return newArray;
}

